mapper.update:
update meal_order
staff_id = #{staffId}, deliver_time = #{deliverTime}, status = #{status}, dine_flag = #{dineFlag}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select mo.*, e.name as elder_name, cs.name as catering_set_name, s.name as staff_name, (select string_agg(od.dishes_name, ',') from meal_order_dishes od where od.meal_order_id = mo.id) as dishes_names from meal_order mo left join elder e on mo.elder_id = e.id left join catering_set cs on mo.catering_set_id = cs.id left join staff s on mo.staff_id = s.id where 1 = 1
and e.name like concat('%', #{elderName}, '%')
and mo.status = #{status}
and mo.dine_date >= #{startDate}
and mo.dine_date <= #{endDate}
order by mo.create_time desc
